import math
    import random
    import time

    LANGUAGE_WRAPPER = 'In triangle ABC with side lengths AB = {ab}, AC = {ac}, and BC = {bc}, let H be the point where the C-symmedian meets AB, and let CH denote this symmedian. Let R and S be the points where the incircles of triangles ACH and BCH, respectively, are tangent to CH. If the length RS can be expressed in lowest terms as m/n, determine m + n.'

    class _RNGShim:
def __init__(self, seed: int):
    import random as _random
    self._seed = int(seed)
    self._r = _random.Random(self._seed)

def random(self): return self._r.random()
def uniform(self, a, b): return self._r.uniform(a, b)
def randint(self, a, b): return self._r.randint(a, b)
def randrange(self, *args): return self._r.randrange(*args)
def choice(self, seq): return self._r.choice(seq)
def choices(self, population, weights=None, cum_weights=None, k: int = 1):
    return self._r.choices(population, weights=weights, cum_weights=cum_weights, k=k)
def sample(self, population, k: int): return self._r.sample(population, k)
def shuffle(self, x):
    self._r.shuffle(x)
    return x
def getrandbits(self, k: int): return self._r.getrandbits(k)

    def generator(rng):
from fractions import Fraction
# Try until a valid non-trivial instance is found
for _ in range(10000):
    ac = rng.randint(6, 40)
    bc = rng.randint(6, 40)
    if ac == bc:
        continue  # avoid trivial median case for symmedian
    low = abs(ac - bc) + 1
    high = ac + bc - 1
    if low >= high:
        continue
    # cap AB to keep answers reasonable
    ab = rng.randint(low, min(high, 60))
    denom = ac*ac + bc*bc
    if denom <= 0:
        continue
    # Symmedian from C divides AB in ratio AH:HB = AC^2 : BC^2
    ah = Fraction(ab * ac*ac, denom)
    # Derived general formula for RS along CH (independent of angle, depends only on AH)
    rs = Fraction(abs(ab - 2*ah - (bc - ac)), 2)
    if rs.numerator == 0:
        continue  # avoid RS = 0
    if rs.denominator == 1:
        continue  # avoid integer RS (too easy)
    if rs.numerator + rs.denominator > 10000:
        continue  # keep m + n within a reasonable range
    return {'ab': ab, 'ac': ac, 'bc': bc}
# Fallback in rare case (should not happen)
return {'ab': 23, 'ac': 17, 'bc': 31}

