    ac = int(assign['ac'])
    bc = int(assign['bc'])
except Exception:
    # Missing or invalid assignments
    return (False, None)
# Basic triangle constraints
if ab <= 0 or ac <= 0 or bc <= 0:
    return (False, None)  # non-positive sides
if ab >= ac + bc or ac >= ab + bc or bc >= ab + ac:
    return (False, None)  # degenerate triangle
if ac == bc:
    return (False, None)  # trivializes symmedian into median
from fractions import Fraction
denom = ac*ac + bc*bc
if denom <= 0:
    return (False, None)
# Symmedian ratio: AH/HB = AC^2/BC^2 -> AH = AB * AC^2 / (AC^2 + BC^2)
ah = Fraction(ab * ac*ac, denom)
# General incircle tangency shift formula along CH:
# RS = |(s_BCH - BC) - (s_ACH - AC)| = |(BH - AH) - (BC - AC)| / 2
rs = Fraction(abs(ab - 2*ah - (bc - ac)), 2)
if rs.numerator == 0:
    return (False, None)  # RS cannot be zero for intended difficulty
if rs.denominator == 1:
    return (False, None)  # avoid integer RS (too easy)
m, n = rs.numerator, rs.denominator
return (True, m + n)


    def generate_valid_instance(seed: int, timeout_seconds: float = 10.0):
        """Return dict with assignment/question/answer or raise RuntimeError."""
        start = time.time()
        attempts = 0
        while time.time() - start < timeout_seconds:
            attempts += 1
            rng = _RNGShim(seed + attempts)
            assignment = generator(rng)
            valid, answer = verifier(assignment)
            if valid:
                question = LANGUAGE_WRAPPER.format(**assignment)
                return {
                    "assignment": assignment,
                    "question": question,
                    "answer": answer,
                    "attempts": attempts,
                    "elapsed_seconds": time.time() - start,
                }
        raise RuntimeError("Failed to sample a valid assignment within timeout_seconds")

